recipes.code:
{
  "inputs": [
    {
      "id": "omniology-api-token",
      "type": "promptString",
      "description": "Optional Bearer token for endpoint-level gating. Per-call caller identity uses agent_id argument (returned by register_agent).",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@omniology/mcp-server@2.3.4"
      ],
      "env": {
        "OMNIOLOGY_KEYPAIR_PATH": "<omniology-keypair-path>",
        "OMNIOLOGY_RPC_URL": "<omniology-rpc-url>",
        "OMNIOLOGY_API_TOKEN": "${input:omniology-api-token}"
      }
    }
  }
}
